using System;using System.Data.SqlClient;
namespace Training.Manager{public partial class FeedbackReport:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();private string MID{get{return Session["ManagerID"]==null?"":Session["ManagerID"].ToString();}}protected void Page_Load(object s,EventArgs e){if(string.IsNullOrWhiteSpace(MID))Response.Redirect("~/Default.aspx");if(!IsPostBack)BindGrid();}
private void BindGrid(){string q="SELECT FD.TrainingID,FD.SessionID,FD.QuestionID,FQM.QuestionText,FD.Rating,FD.Answer,F.Submitted,F.CreatedOn FROM FeedbackDetail FD INNER JOIN Feedback F ON FD.FeedbackID=F.FeedbackID INNER JOIN FeedbackQuestionMaster FQM ON FD.QuestionID=FQM.QuestionID INNER JOIN TrainingDetails TD ON FD.TrainingID=TD.TrainingID INNER JOIN TrainingLocationMaster L ON TD.TrainingLocation=L.TrainingLocation INNER JOIN ManagerMaster M ON M.TrainingLocationID=L.TrainingLocationID WHERE M.ManagerID=@ManagerID AND ISNULL(M.ActiveStatus,'Y')='Y' AND F.Submitted=1";var p=new System.Collections.Generic.List<SqlParameter>();p.Add(new SqlParameter("@ManagerID",MID));if(!string.IsNullOrWhiteSpace(txtTrainingID.Text)){q+=" AND FD.TrainingID=@TrainingID";p.Add(new SqlParameter("@TrainingID",txtTrainingID.Text.Trim()));}if(!string.IsNullOrWhiteSpace(txtSessionID.Text)){q+=" AND FD.SessionID=@SessionID";p.Add(new SqlParameter("@SessionID",txtSessionID.Text.Trim()));}q+=" ORDER BY FD.CreatedOn DESC";gvFeedback.DataSource=obj.GetDataTable(q,p.ToArray());gvFeedback.DataBind();}protected void btnSearch_Click(object s,EventArgs e){BindGrid();}}}